-- 301: SG-only site — remove Malaysia/Ghana links from SG footer block and
-- trainer-bio CMS pages. REPLACE() args are UNHEX() of the exact live bytes
-- (generated programmatically); no-op wherever the substring is absent, so
-- safe on country instances whose block/page ids hold different content.

UPDATE cms_block SET content = REPLACE(content, UNHEX(''), '') WHERE block_id = 7;

UPDATE cms_block SET content = REPLACE(content, UNHEX(''), '') WHERE block_id = 7;

UPDATE cms_page SET content = REPLACE(content, UNHEX(''), '') WHERE page_id IN (24, 30);
